fields.InputDefinition:
{
  "goal": "Switch to the Knowledge Hub app (application switcher dropdown next to the logo) and click 'Analytics' in the left nav (fa-chart-line icon). Then walk these sections IN ORDER, and as you arrive at each set \"checkpointReached\" to the exact checkpoint name shown: (1) analytics-drilldown — confirm the Overview section renders its KPI cards and widget grid, then click a different section in the left-nav rail (e.g. Tags or Quality) and confirm the main content swaps; back on Overview, click a KPI card and confirm a drill-down detail panel opens (with a table or a 'No data available' empty state); (2) cooccurrence-recompute — open the 'Tags' section and scroll to the 'Frequently Paired Tags' (co-occurrence) sub-section, click the 'Recompute' button, and confirm it enters a Computing/disabled state and afterward shows the co-occurrence table with tag pairs OR a valid 'No co-occurrence data' empty state. Keep going until both sections have been visited. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "analytics-drilldown",
      "instruction": "rail navigation + KPI drill-down",
      "visualCriteria": [
        "The Analytics Overview renders KPI cards and a widget grid, switching sections in the left-nav rail swaps the main content, and clicking a KPI card opens a drill-down detail panel (table or valid empty state)"
      ]
    },
    {
      "name": "cooccurrence-recompute",
      "instruction": "Tags co-occurrence recompute",
      "visualCriteria": [
        "The Analytics Tags section shows a 'Frequently Paired Tags' area with a Recompute button, and clicking Recompute enters a Computing/disabled state and then shows the co-occurrence table or a valid empty state"
      ]
    }
  ]
}
